using System;using System.IO;using System.Collections.Generic;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using NeonVault;
[InitializeOnLoad] public static class SafehouseVisualQA {
 const string Output="D:/Unity/AssetIntegration/SafehouseLightQA-20261028-revised";static int stage,frame;static Transform interior,exterior;static Vector3 camp;
 static SafehouseVisualQA(){if(SessionState.GetBool("SafehouseLightQA",false))EditorApplication.update+=Tick;}
 public static void Run(){Directory.CreateDirectory(Output);SessionState.SetBool("SafehouseLightQA",true);EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);EditorApplication.isPlaying=true;}
 static void Tick(){try{if(!EditorApplication.isPlaying)return;if(stage==0){var layout=new SectorLayout(new System.Random(17017));Array.Clear(layout.open,0,layout.open.Length);for(int x=0;x<layout.Columns;x++)for(int y=0;y<layout.Rows;y++){var p=layout.Center(new Vector2Int(x,y));if(new Vector2(p.x,p.z).magnitude<13.5f)layout.open[x,y]=true;}layout.walls.Clear();layout.covers.Clear();interior=new GameObject("Safehouse interior").transform;var mats=new List<Material>();var art=new VaultArt(interior,mats,new System.Random(17017));art.Floor(16,15,0);for(int i=0;i<8;i++){float a=i*Mathf.PI/4;art.Column(new Vector3(Mathf.Sin(a)*12.5f,0,Mathf.Cos(a)*12.5f),2.5f);}ImportedWorldAssets.DressInterior(interior,layout,true);
 exterior=new GameObject("Exterior").transform;var geo=new OverworldGeography();camp=geo.Camps[0];WorldEntranceBuildings.AssetAdapter=ImportedWorldAssets.Place;WorldEntranceBuildings.Build(exterior,mats,geo);WorldEntranceBuildings.UpdateFocus(exterior,camp);var sun=new GameObject("sun").AddComponent<Light>();sun.type=LightType.Directional;sun.intensity=1.2f;sun.transform.rotation=Quaternion.Euler(50,-30,0);RenderSettings.ambientLight=Color.gray;stage=1;frame=Time.frameCount;return;}if(Time.frameCount<frame+5)return;
 int inside=0,perimeter=0,defense=0;var list=new System.Text.StringBuilder();foreach(var t in UnityEngine.Object.FindObjectsByType<Transform>(FindObjectsSortMode.None)){if(t.name.StartsWith("Safehouse interior / "))inside++;else if(t.name.StartsWith("Safehouse perimeter / "))perimeter++;else if(t.name.StartsWith("Camp defense / "))defense++;else continue;list.AppendLine(t.name+" "+t.position);}list.Insert(0,"interior="+inside+" perimeter="+perimeter+" defense="+defense+"\n");File.WriteAllText(Output+"/counts.txt",list.ToString());var cam=new GameObject("QA camera").AddComponent<Camera>();cam.orthographic=true;cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=new Color(.12f,.14f,.16f);cam.farClipPlane=150;exterior.gameObject.SetActive(false);cam.orthographicSize=23;cam.transform.position=new Vector3(0,35,-32);cam.transform.LookAt(Vector3.zero);Capture(cam,"interior-overview");cam.orthographicSize=12;cam.transform.position=new Vector3(-29,18,0);cam.transform.LookAt(new Vector3(-15,0,0));Capture(cam,"interior-west");interior.gameObject.SetActive(false);exterior.gameObject.SetActive(true);cam.orthographicSize=12;cam.transform.position=camp+new Vector3(0,12,-22);cam.transform.LookAt(camp+new Vector3(0,2,3));Capture(cam,"entrance-front");Debug.Log("SAFEHOUSE_LIGHT_QA_COMPLETE interior="+inside+" perimeter="+perimeter+" defense="+defense);SessionState.SetBool("SafehouseLightQA",false);EditorApplication.Exit(0);
 }catch(Exception e){File.WriteAllText(Output+"/error.txt",e.ToString());Debug.LogException(e);SessionState.SetBool("SafehouseLightQA",false);EditorApplication.Exit(1);}}
 static void Capture(Camera cam,string name){var rt=new RenderTexture(1280,900,24);cam.targetTexture=rt;foreach(var batch in UnityEngine.Object.FindObjectsByType<ImportedWorldBatch>(FindObjectsSortMode.None))batch.DrawNow();cam.Render();RenderTexture.active=rt;var tex=new Texture2D(1280,900,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1280,900),0,0);tex.Apply();File.WriteAllBytes(Output+"/"+name+".png",tex.EncodeToPNG());cam.targetTexture=null;RenderTexture.active=null;rt.Release();UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(tex);}
}

